"to_missing":"ز"},{"id":"62518a73-f21a-4dc1-bb17-d43f21980933","from_word":"قَا_","from_missing":"ضٍ","to_word":"قا_","to_missing":"ض"},{"id":"64d9e5ea-8414-4a78-a29a-b59d5c5eb7c4","from_word":"_جَّارٌ","from_missing":"نَ","to_word":"_جّار","to_missing":"ن"},{"id":"6c92a3fc-8426-4bc9-94c7-6bd213d314ae","from_word":"سَائِقُ حَا_لَةٍ","from_missing":"فِ","to_word":"سائق حا_لة","to_missing":"ف"},{"id":"6f88f6cd-8c4c-43b0-a7aa-ed6eab68dd9e","from_word":"مِيكَا_يكِيٌّ","from_missing":"نِ","to_word":"ميكا_يكي","to_missing":"ن"},{"id":"876b6776-714e-4451-94ff-28d3494d7c03","from_word":"عَامِلُ بِ_اءٍ","from_missing":"نَ","to_word":"عامل ب_اء","to_missing":"ن"},{"id":"a2fe9de0-4d94-4d69-99b3-adc3328564e9","from_word":"طَ_يبٌ","from_missing":"بِ","to_word":"ط_يب","to_missing":"ب"},{"id":"a69be569-59c2-4f98-840c-734a331fe600","from_word":"مُ_امٍ","from_missing":"حَ","to_word":"م_ام","to_missing":"ح"},{"id":"b448d4bf-bf82-4f2c-b87d-a64bbeefba2f","from_word":"طَبِيبٌ _يْطَرِيٌّ","from_missing":"بَ","to_word":"طبيب _يطري","to_missing":"ب"},{"id":"b9e76e35-9365-4c84-aee1-cd690c95bb1d","from_word":"تِلْ_يذٌ","from_missing":"مِ","to_word":"تل_يذ","to_missing":"م"},{"id":"bcff43de-17ca-4f70-a180-d83836e8734f","from_word":"طَ_ارٌ","from_missing":"يَّ","to_word":"ط_ار","to_missing":"ي"},{"id":"bf3dac0e-1d9f-4678-a7e8-1f286f837ffb","from_word":"فَلَّا_","from_missing":"حٌ","to_word":"فلّا_","to_missing":"ح"},{"id":"c8c509ed-fcc5-4be3-9f62-88cab650a85c","from_word":"عَامِلُ نَ_افَةٍ","from_missing":"ظَ","to_word":"عامل ن_افة","to_missing":"ظ"},{"id":"d84de957-fd58-4700-bfef-87b1ee5bd04a","from_word":"جَزَّا_","from_missing":"رٌ","to_word":"جزّا_","to_missing":"ر"},{"id":"d96866ab-2160-4cd1-baf7-d4ea9583c6a8","from_word":"رَجُلُ إِطْ_اءٍ","from_missing":"فَ","to_word":"رجل إط_اء","to_missing":"ف"},{"id":"f71aed5a-d374-466b-b65d-966fcd340acb","from_word":"شُرْطِيُّ مُ_ورٍ","from_missing":"رُ","to_word":"شرطيّ م_ور","to_missing":"ر"},{"id":"f80a142e-e0cb-416f-91e2-8bbb3bc12b78","from_word":"كَا_بٌ","from_missing":"تِ","to_word":"كا_ب","to_missing":"ت"},{"id":"ffbede67-5303-4c97-85cb-9d52284884a7","from_word":"مُهَنْ_سٌ","from_missing":"دِ","to_word":"مهن_س","to_missing":"د"}]$labels$::jsonb;
  matching integer;
BEGIN
  SELECT count(*) INTO matching
  FROM jsonb_to_recordset(changes) AS c(id uuid, from_word text, from_missing text, to_word text, to_missing text)
  JOIN public.letter_catcher_words w ON w.id = c.id
  WHERE (w.word = c.from_word AND w.missing_letter = c.from_missing)
     OR (w.word = c.to_word AND w.missing_letter = c.to_missing);
  IF matching <> 271 THEN
    RAISE EXCEPTION 'Vocalization stopped: expected 271 matching labels, found %', matching;
  END IF;
  UPDATE public.letter_catcher_words w
  SET word = c.to_word, missing_letter = c.to_missing
  FROM jsonb_to_recordset(changes) AS c(id uuid, from_word text, from_missing text, to_word text, to_missing text)
  WHERE w.id = c.id
    AND w.word = c.from_word AND w.missing_letter = c.from_missing
    AND (w.word IS DISTINCT FROM c.to_word OR w.missing_letter IS DISTINCT FROM c.to_missing);
END
$vocalization$;
COMMIT;
